      "sourceMarkdown": "### P01-03 — в виду\n\nВпоследствии всё прояснилось: мой друг, оказывается, имел (В)ВИДУ совсем другое.\n\n- **Маска:** `(В)ВИДУ`.\n- **Нормативное написание:** в виду.\n- **Тип написания:** раздельно.\n- **Грамматика:** В + существительное вид в предложном падеже; часть оборота иметь в виду.\n- **Объяснение:** Имел в виду означает подразумевал. В устойчивом обороте сохраняется раздельное написание предлога в и существительного виду; причины последующего события эта группа не выражает.\n- **Источник:** d50, вариант 34, строка 2 (d50-v34-p2).\n- **Прослеживаемость:** `ege14-raw-04898255e7e851d53488cefb81d5755db60377b1bc3a0709044e03c16249b5f2:4`; `research/stage1/classified_batch_01_v2.json#/records/13/contexts/3`; абзац XML 8982 (от нуля).\n- **Исходная строка:** (В)ПОСЛЕДСТВИИ всё прояснилось: мой друг, оказывается, имел (В)ВИДУ совсем другое.\n- **Различие контекста:** Выяснение намерения собеседника.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P01.B:** Слить в виду в обороте иметь в виду. **Верная стратегия:** Распознать устойчивое сочетание с существительным вид; сохранить пробел.\n- **Основания:** N140, G_VIEW — см. [нормативные источники](normative_sources.md).",
