      "sourceMarkdown": "### P01-06 — в виду\n\nШхуна остановилась (В)ВИДУ берега и до рассвета не снималась с якоря.\n\n- **Маска:** `(В)ВИДУ`.\n- **Нормативное написание:** в виду.\n- **Тип написания:** раздельно.\n- **Грамматика:** В + существительное вид в предложном падеже; книжное пространственное сочетание.\n- **Объяснение:** Шхуна остановилась там, откуда виден берег, а не по причине берега. Сочетание в виду берега имеет пространственное значение и пишется раздельно; книжная окраска не меняет написания.\n- **Источник:** авторский; подготовлен для блока «Предлоги».\n- **Различие контекста:** Морская стоянка; книжное употребление.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P01.C:** Считать любое сочетание перед родительным падежом причинным ввиду. **Верная стратегия:** Отличить пространственную видимость от причины; в виду в значении в пределах видимости раздельно.\n- **Основания:** N140, G_VIEW — см. [нормативные источники](normative_sources.md).",
