      "sourceMarkdown": "### P03-04 — на счёт\n\nПожертвования поступили (НА)СЧЁТ фонда раньше, чем организаторы ожидали.\n\n- **Маска:** `(НА)СЧЁТ`.\n- **Нормативное написание:** на счёт.\n- **Тип написания:** раздельно.\n- **Грамматика:** На + существительное счёт, винительный падеж.\n- **Объяснение:** Счёт фонда — банковский счёт, на который поступили средства. Форма фонда зависит от существительного счёт; это не основание писать насчёт. Предлог на сохраняет самостоятельность.\n- **Источник:** авторский; подготовлен для блока «Предлоги».\n- **Различие контекста:** Зачисление пожертвований.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P03.B:** Слить на счёт при названии получателя средств. **Верная стратегия:** Счёт — существительное в винительном падеже при глаголе перевода или зачисления; на отдельно.\n- **Основания:** N140 — см. [нормативные источники](normative_sources.md).",
