      "sourceMarkdown": "### P04-03 — на встречу\n\nДети взяли по одному бутерброду и пошли (НА)ВСТРЕЧУ с вожатыми.\n\n- **Маска:** `(НА)ВСТРЕЧУ`.\n- **Нормативное написание:** на встречу.\n- **Тип написания:** раздельно.\n- **Грамматика:** На + существительное встреча, винительный падеж.\n- **Объяснение:** Дети пошли на событие — встречу с вожатыми. Существительное встреча сохраняет значение мероприятия и имеет зависимую группу с вожатыми. На пишется отдельно.\n- **Источник:** d50, вариант 6, строка 3 (d50-v06-p3).\n- **Прослеживаемость:** `ege14-raw-1459372afb44b9388896ac9f90112925526cbccc10f749f1a96929c5d6ca4450:1`; `research/stage1/classified_batch_02.json#/records/17/contexts/0`; абзац XML 1416 (от нуля).\n- **Исходная строка:** Дети взяли (ПО)ОДНОМУ бутерброду и пошли (НА)ВСТРЕЧУ с вожатыми.\n- **Различие контекста:** Организованное событие с участниками.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P04.B:** Слить на встречу, потому что глагол обозначает движение. **Верная стратегия:** Проверить, названо ли событие встреча; на + винительный падеж пишутся отдельно.\n- **Основания:** G_MEET, N136 — см. [нормативные источники](normative_sources.md).",
