      "sourceMarkdown": "### P06-09 — на протяжении\n\n(НА)ПРОТЯЖЕНИИ полутора столетий происходило постепенное территориальное расширение вотчины московских князей за счёт других княжеств.\n\n- **Маска:** `(НА)ПРОТЯЖЕНИИ`.\n- **Нормативное написание:** на протяжении.\n- **Тип написания:** раздельно.\n- **Грамматика:** Составной производный предлог времени с родительным падежом.\n- **Объяснение:** Полтора столетия — длительность исторического процесса. Составной предлог на протяжении пишется раздельно; конечное ии сохраняется в его закреплённой форме.\n- **Источник:** d50, вариант 23, строка 5 (d50-v23-p5).\n- **Прослеживаемость:** `ege14-raw-d21ae7cff4bf7a9ef41706957a0262ca11ded1c30356066bd33b3b852e1715d3:2`; `research/stage1/classified_batch_03.json#/records/10/contexts/1`; абзац XML 5979 (от нуля).\n- **Исходная строка:** (НА)ПРОТЯЖЕНИИ полутора столетий происходило постепенное территориальное расширение вотчины московских князей (ЗА)СЧЁТ других княжеств.\n- **Различие контекста:** Длительный исторический процесс.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P06.E:** Слить на протяжении по аналогии с однословным предлогом. **Верная стратегия:** Составной предлог длительности на протяжении сохраняет пробел и конечное ии.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
