      "sourceMarkdown": "### P06-12 — в заключение\n\n(В)ЗАКЛЮЧЕНИЕ показа зрители задали режиссёру несколько вопросов о работе над фильмом.\n\n- **Маска:** `(В)ЗАКЛЮЧЕНИЕ`.\n- **Нормативное написание:** в заключение.\n- **Тип написания:** раздельно.\n- **Грамматика:** Составной производный предлог с родительным падежом; значение завершения.\n- **Объяснение:** Зрители задавали вопросы под конец показа. В заключение обозначает завершающий этап события и пишется в два слова с конечным е. Форму предложного падежа заключении здесь не выбирают.\n- **Источник:** авторский; подготовлен для блока «Предлоги».\n- **Различие контекста:** Завершение кинопоказа.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P06.F:** Слить в заключение либо написать и в предлоге завершения. **Верная стратегия:** Предлог со значением под конец пишется раздельно, с конечным е.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
