      "sourceMarkdown": "### P07-05 — за счёт\n\nНовый административный округ Москвы образован (ЗА)СЧЁТ территории, примыкавшей к границе столицы на юго-западе.\n\n- **Маска:** `(ЗА)СЧЁТ`.\n- **Нормативное написание:** за счёт.\n- **Тип написания:** раздельно.\n- **Грамматика:** Составной производный предлог с родительным падежом.\n- **Объяснение:** За счёт территории указывает, из каких земель образован округ. Составной предлог за счёт пишется раздельно; единство значения не делает его однословным.\n- **Источник:** d36, вариант 17, строка 4 (d36-v17-p4).\n- **Прослеживаемость:** `ege14-raw-cb6501d852c9efb6552993cd880587aec61b9cba11eca8e951fec37be9807c68:2`; `research/stage1/classified_batch_05.json#/records/21/contexts/1`; абзац XML 6949 (от нуля).\n- **Исходная строка:** Новый административный округ Москвы образован (ЗА)СЧЁТ территории, примыкавшей к границе столицы на (ЮГО)ЗАПАДЕ.\n- **Различие контекста:** Образование территории.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P07.C:** Слить части сочетания за счёт, потому что оно выполняет функцию одного предлога. **Верная стратегия:** Распознать составной предлог за счёт; его грамматическое единство не отменяет пробелов между словами.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
