      "sourceMarkdown": "### P07-09 — в отличие\n\n(В)ОТЛИЧИЕ от городских ополчений, состоявших из рядового населения и набиравшихся для долгих походов или каких-то крупных сражений, дружина представляла собой военную элиту.\n\n- **Маска:** `(В)ОТЛИЧИЕ`.\n- **Нормативное написание:** в отличие.\n- **Тип написания:** раздельно.\n- **Грамматика:** Часть составного предлога в отличие от; от + родительный падеж.\n- **Объяснение:** Дружина сопоставляется с ополчениями по противопоставительному признаку. Полное сочетание в отличие от пишется раздельно; в целевой части сохраняется е, компонент от дан вне скобок.\n- **Источник:** d50, вариант 43, строка 4 (d50-v43-p4).\n- **Прослеживаемость:** `ege14-raw-a4f34858ac393a7c76e9b049d4f73f7717a5b7656bf2e7f4624d1700a56bce89:1`; `research/stage1/classified_batch_09.json#/records/2/contexts/0`; абзац XML 11202 (от нуля).\n- **Исходная строка:** (В)ОТЛИЧИЕ от городских ополчений, состоявших из рядового населения и набиравшихся для долгих походов или КАКИХ(ТО) крупных сражений, дружина представляла собой военную элиту.\n- **Различие контекста:** Историческое сопоставление.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P07.E:** Слить части сочетания в отличие от, потому что оно выполняет функцию одного предлога. **Верная стратегия:** Распознать составной предлог в отличие от; его грамматическое единство не отменяет пробелов между словами.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
