      "sourceMarkdown": "### P07-12 — в ходе\n\n(В)ХОДЕ реставрации под поздней штукатуркой обнаружили фрагменты старинной росписи.\n\n- **Маска:** `(В)ХОДЕ`.\n- **Нормативное написание:** в ходе.\n- **Тип написания:** раздельно.\n- **Грамматика:** Составной производный предлог с родительным падежом.\n- **Объяснение:** Сочетание в ходе реставрации обозначает процесс, во время которого обнаружили роспись. В ходе — составной предлог, пишущийся раздельно; реставрации стоит в родительном падеже.\n- **Источник:** авторский; подготовлен для блока «Предлоги».\n- **Различие контекста:** Находка во время работы.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P07.F:** Слить части сочетания в ходе, потому что оно выполняет функцию одного предлога. **Верная стратегия:** Распознать составной предлог в ходе; его грамматическое единство не отменяет пробелов между словами.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
