      "sourceMarkdown": "### P07-16 — в силу\n\n(В)СИЛУ того что рукопись сохранилась не полностью, исследователи отказались от категорических выводов.\n\n- **Маска:** `(В)СИЛУ`.\n- **Нормативное написание:** в силу.\n- **Тип написания:** раздельно.\n- **Грамматика:** Целевая часть составного причинного союза в силу того что.\n- **Объяснение:** Причина выражена придаточной частью с основой рукопись сохранилась. Весь оборот в силу того что — союз, а не предлог с существительным; в целевой части остаются два слова.\n- **Источник:** авторский; подготовлен для блока «Предлоги».\n- **Различие контекста:** Причинная придаточная часть; работа с рукописью.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P07.H:** Назвать предлогом всю конструкцию в силу того что перед придаточной частью. **Верная стратегия:** Различить предлог при имени и составной причинный союз перед предикативной частью; в силу сохраняет пробел.\n- **Примечание:** Пунктуация дана при нерасчленённом составном союзе; вопрос о границе союза не является целью карточки.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
