      "sourceMarkdown": "### P08-03 — позади\n\nМартын плёлся к реке и слушал, как (ПО)ЗАДИ него понемногу замирали звуки свирели.\n\n- **Маска:** `(ПО)ЗАДИ`.\n- **Нормативное написание:** позади.\n- **Тип написания:** слитно.\n- **Грамматика:** Производный пространственный предлог с родительным падежом местоимения него.\n- **Объяснение:** Позади него указывает положение звуков относительно Мартына. Предлог управляет родительным него и пишется слитно; наличие местоимения не требует пробела внутри позади.\n- **Источник:** d50, вариант 9, строка 2 (d50-v09-p2).\n- **Прослеживаемость:** `ege14-raw-f75701e9a3e51b129ee9a38f780348cd891158e5589a0fb0aa31e36b2b3e2ceb:1`; `research/stage1/classified_batch_03.json#/records/2/contexts/0`; абзац XML 2224 (от нуля).\n- **Исходная строка:** Мартын плёлся к реке и слушал, как (ПО)ЗАДИ него (ПО)НЕМНОГУ замирали звуки свирели.\n- **Различие контекста:** Место относительно идущего человека.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P08.A:** Считать зависимое имя универсальным основанием для раздельного написания. **Верная стратегия:** Определить закреплённый производный предлог и его управление; наличие имени не разрывает слово.\n- **Основания:** N136, N140, LOCAL — см. [нормативные источники](normative_sources.md).",
