      "sourceMarkdown": "### P08-09 — наряду\n\n(НА)РЯДУ с рукописями в витринах были представлены прижизненные фотографии писателя.\n\n- **Маска:** `(НА)РЯДУ`.\n- **Нормативное написание:** наряду.\n- **Тип написания:** слитно.\n- **Грамматика:** Часть составного производного предлога наряду с; творительный падеж.\n- **Объяснение:** Наряду с рукописями присоединяет ещё один вид экспонатов на равных основаниях. Наряду пишется слитно, с — отдельно; рукописями имеет творительный падеж. Это сопоставительное, а не пространственное отношение.\n- **Источник:** авторский; подготовлен для блока «Предлоги».\n- **Различие контекста:** Равноправное включение видов экспонатов.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P08.D:** Разделить наряду в составном предлоге наряду с. **Верная стратегия:** Слово наряду пишется слитно; последующее с — отдельный компонент предлога с творительным падежом.\n- **Основания:** N136, N140, LOCAL — см. [нормативные источники](normative_sources.md).",
