      "sourceMarkdown": "### P08-17 — вслед\n\nЕё большие светло-голубые глаза засияли от счастья, когда (В)СЛЕД за горничной на пороге появился давний приятель семьи.\n\n- **Маска:** `(В)СЛЕД`.\n- **Нормативное написание:** вслед.\n- **Тип написания:** слитно.\n- **Грамматика:** Слитный компонент составного предлога вслед за; за + творительный падеж.\n- **Объяснение:** Вслед за горничной обозначает последовательное появление людей. Вслед пишется одним словом, за остаётся отдельным компонентом предлога и вводит творительный горничной. Раздельность вслед не возникает из-за следующего за.\n- **Источник:** d50, вариант 22, строка 3 (d50-v22-p3).\n- **Прослеживаемость:** `ege14-raw-d25c3d89cc25a57f293ac9cbf7175fea5b31832c9dd21ec2fbcb0162086a7aa5:2`; `research/stage1/classified_batch_01_v2.json#/records/19/contexts/1`; абзац XML 5731 (от нуля).\n- **Исходная строка:** Её большие (СВЕТЛО)ГОЛУБЫЕ глаза засияли от счастья, когда (В)СЛЕД за горничной на пороге появился давний приятель семьи.\n- **Различие контекста:** Следование за человеком; составной предлог.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P08.A:** Считать зависимое имя универсальным основанием для раздельного написания. **Верная стратегия:** Определить закреплённый производный предлог и его управление; наличие имени не разрывает слово.\n- **Основания:** N136, N140, LOCAL — см. [нормативные источники](normative_sources.md).",
