      "sourceMarkdown": "### P09-03 — из-под\n\n(ИЗ)ПОД снега вода находит себе путь к реке, и понемногу лёд поднимается.\n\n- **Маска:** `(ИЗ)ПОД`.\n- **Нормативное написание:** из-под.\n- **Тип написания:** через дефис.\n- **Грамматика:** Сложный непроизводный пространственный предлог с родительным падежом.\n- **Объяснение:** Из-под снега обозначает исходную область движения воды — под снежным покровом. Сложный предлог из-под пишется через дефис; отдельные из и под в этой позиции не образуют двух групп.\n- **Источник:** d36, вариант 20, строка 1 (d36-v20-p1).\n- **Прослеживаемость:** `ege14-raw-e451e0493b8c93e838d21b3a1199bc4d08f2bc0921693730863142b58f79dded:1`; `research/stage1/classified_batch_12.json#/records/4/contexts/0`; абзац XML 7868 (от нуля).\n- **Исходная строка:** (ИЗ)ПОД снега вода находит себе путь к реке, и (ПО)НЕМНОГУ лёд поднимается.\n- **Различие контекста:** Движение из-под покрова.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P09.B:** Писать из-под двумя словами или слитно при переносном значении. **Верная стратегия:** Дефис закреплён в сложном непроизводном предлоге из-под, в том числе при указании прежнего содержимого ёмкости.\n- **Основания:** LOCAL — см. [нормативные источники](normative_sources.md).",
