      "sourceMarkdown": "### P10-02 — за границей\n\nВсе Гришины одноклассники уже побывали (ЗА)ГРАНИЦЕЙ, и он был чуть ли не единственным, кого не вывозили никуда дальше Красной Пахры.\n\n- **Маска:** `(ЗА)ГРАНИЦЕЙ`.\n- **Нормативное написание:** за границей.\n- **Тип написания:** раздельно.\n- **Грамматика:** За + существительное граница, творительный падеж; устойчивое обстоятельственное сочетание.\n- **Объяснение:** За границей означает в другой стране, но устойчивое значение не отменяет пробела. Это сочетание предлога и падежной формы существительного, а не одно слово заграница.\n- **Источник:** d50, вариант 7, строка 2 (d50-v07-p2).\n- **Прослеживаемость:** `ege14-raw-9377e1e933141252ccca2546c70ce8941367b741b29b03d9fb117044f1870cba:1`; `research/stage1/classified_batch_02.json#/records/21/contexts/0`; абзац XML 1684 (от нуля).\n- **Исходная строка:** Все Гришины одноклассники уже побывали (ЗА)ГРАНИЦЕЙ, и он был ЧУТЬ(ЛИ) не единственным, кого не вывозили никуда дальше Красной Пахры.\n- **Различие контекста:** Место пребывания.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P10.A:** Слить обстоятельственную группу, поскольку она отвечает на вопрос где/куда/как. **Верная стратегия:** Вопрос к группе не отменяет самостоятельности предлога и существительного; проверить значение и падеж.\n- **Основания:** N137, LOCAL — см. [нормативные источники](normative_sources.md).",
