      "sourceMarkdown": "### P10-04 — с интересом\n\nМальчишки (С)ИНТЕРЕСОМ смотрели вслед уходящему паруснику.\n\n- **Маска:** `(С)ИНТЕРЕСОМ`.\n- **Нормативное написание:** с интересом.\n- **Тип написания:** раздельно.\n- **Грамматика:** С + существительное интерес, творительный падеж.\n- **Объяснение:** С интересом характеризует отношение наблюдателей к происходящему. Значение образа действия не превращает сочетание в одно наречие: с — самостоятельный предлог при существительном.\n- **Источник:** d50, вариант 3, строка 1 (d50-v03-p1).\n- **Прослеживаемость:** `ege14-raw-bcd941e2bed06084046e74172675d3d0d84ceb6dbbc446628aea9648b0e0c4c6:1`; `research/stage1/classified_batch_01_v2.json#/records/18/contexts/0`; абзац XML 682 (от нуля).\n- **Исходная строка:** Мальчишки (С)ИНТЕРЕСОМ смотрели (В)СЛЕД уходящему паруснику.\n- **Различие контекста:** Отношение наблюдателей.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P10.A:** Слить обстоятельственную группу, поскольку она отвечает на вопрос где/куда/как. **Верная стратегия:** Вопрос к группе не отменяет самостоятельности предлога и существительного; проверить значение и падеж.\n- **Основания:** N137, LOCAL — см. [нормативные источники](normative_sources.md).",
