      "sourceMarkdown": "### P10-09 — до конца\n\nКолумб (ДО)КОНЦА своих дней думал, что проложил новый путь в Индию, поэтому новый материк долго называли Вест-Индией.\n\n- **Маска:** `(ДО)КОНЦА`.\n- **Нормативное написание:** до конца.\n- **Тип написания:** раздельно.\n- **Грамматика:** До + существительное конец, родительный падеж; временная граница.\n- **Объяснение:** До конца своих дней задаёт предел длительности убеждения. Конца — падежная форма существительного с зависимой группой своих дней; до пишется отдельно.\n- **Источник:** d50, вариант 36, строка 3 (d50-v36-p3).\n- **Прослеживаемость:** `ege14-raw-8f15c2616d1dc0fdd4857afa3cdc7a77d537a7e9d50e449adfe8fa8de0204b8b:1`; `research/stage1/classified_batch_08.json#/records/3/contexts/0`; абзац XML 9495 (от нуля).\n- **Исходная строка:** Колумб (ДО)КОНЦА своих дней думал, что проложил новый путь в Индию, (ПО)ЭТОМУ новый материк долго называли Вест-Индией.\n- **Различие контекста:** Временной предел с определением.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P10.B:** Слить предлог с именем при устойчивости выражения или зависимом определении. **Верная стратегия:** Сохранить границы слов в устойчивом сочетании и при определении; обстоятельственная функция не равна наречию-слову.\n- **Основания:** N137, LOCAL — см. [нормативные источники](normative_sources.md).",
