      "sourceMarkdown": "### P10-12 — к вершине\n\nТуристы вспоминали своё первое восхождение (К)ВЕРШИНЕ, которая сначала казалась им недосягаемой.\n\n- **Маска:** `(К)ВЕРШИНЕ`.\n- **Нормативное написание:** к вершине.\n- **Тип написания:** раздельно.\n- **Грамматика:** К + существительное вершина, дательный падеж.\n- **Объяснение:** Вершина — цель восхождения, выраженная существительным в дательном падеже. Предлог к связывает его с названием движения и пишется отдельно; зависимое которая подтверждает предметное значение вершины.\n- **Источник:** d36, вариант 16, строка 1 (d36-v16-p1).\n- **Прослеживаемость:** `ege14-raw-a7fb15986d839eccad263329e2eb5da9b388f1102b3ae8c884e8f3a775a53498:1`; `research/stage1/classified_batch_11.json#/records/25/contexts/0`; абзац XML 6622 (от нуля).\n- **Исходная строка:** Туристы вспоминали своё первое восхождение (К)ВЕРШИНЕ, которая (С)НАЧАЛА казалась им недосягаемой.\n- **Различие контекста:** Направление с дательным падежом.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P10.A:** Слить обстоятельственную группу, поскольку она отвечает на вопрос где/куда/как. **Верная стратегия:** Вопрос к группе не отменяет самостоятельности предлога и существительного; проверить значение и падеж.\n- **Основания:** N137, LOCAL — см. [нормативные источники](normative_sources.md).",
