      "sourceMarkdown": "### P10-14 — в конце\n\nОсень наступает здесь (В)КОНЦЕ ноября, и только тогда деревья на склонах гор становятся ярко-золотыми, радуя глаз и умиротворяя душу.\n\n- **Маска:** `(В)КОНЦЕ`.\n- **Нормативное написание:** в конце.\n- **Тип написания:** раздельно.\n- **Грамматика:** В + существительное конец, предложный падеж; временное сочетание, допускающее предложную трактовку всей группы.\n- **Объяснение:** В конце ноября обозначает конечную часть месяца; при учебном именном разборе ноября зависит от существительного конце. В пишется отдельно. При описании в конце как предложной единицы написание тоже остаётся раздельным.\n- **Источник:** d36, вариант 31, строка 3 (d36-v31-p3).\n- **Прослеживаемость:** `ege14-raw-d5d7c7d6ec87f00a14364167f9cf81b5b8619e7bec3059907e96fc8b05efa1b2:1`; `research/stage1/classified_batch_13.json#/records/5/contexts/0`; абзац XML 11093 (от нуля).\n- **Исходная строка:** Осень наступает здесь (В)КОНЦЕ ноября, и только тогда деревья на склонах гор становятся ЯРКО(ЗОЛОТЫМИ), радуя глаз и умиротворяя душу.\n- **Различие контекста:** Конечная часть календарного периода.\n- **Статус:** готов к согласованию; автоматическая проверка выключена.\n- **Дистрактор P10.B:** Слить предлог с именем при устойчивости выражения или зависимом определении. **Верная стратегия:** Сохранить границы слов в устойчивом сочетании и при определении; обстоятельственная функция не равна наречию-слову.\n- **Примечание:** Сохранён именной разбор матрицы; альтернативная терминология не создаёт альтернативного написания.\n- **Основания:** N137, LOCAL — см. [нормативные источники](normative_sources.md).",
