      "sourceMarkdown": "### P12-02 — несмотря\n\nВ научной литературе можно встретить много различных оценок рассматриваемого явления, (НЕ)СМОТРЯ на небольшое количество исследований по соответствующей теме.\n\n- **Маска:** `(НЕ)СМОТРЯ`; **ответ:** несмотря; **тип:** слитно.\n- **Грамматика:** Компонент составного уступительного предлога несмотря на; винительный количество.\n- **Объяснение:** Небольшое число исследований противопоставлено множеству оценок: ожидаемого ограничения не произошло. Это отношение между обстоятельством и сообщением, а не зрительное действие лица. В предлоге несмотря пишется слитно; на остаётся отдельным словом.\n- **Пунктуация и связи:** Конечный распространённый уступительный оборот обособлен.\n- **Отличие ситуации:** Уступка в научном рассуждении; без названного деятеля.\n- **Источник:** d50, абзац XML 12964 (от нуля).\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P12.A:** Объявить НЕ отдельной частицей при любом сходстве со словом смотреть. **Стратегия различения:** Установить уступительное отношение: названное обстоятельство не помешало событию, зрительного действия нет.\n- **Точная исходная строка / транскрипция:** В научной литературе можно встретить много различных оценок рассматриваемого явления, (НЕ)СМОТРЯ на небольшое количество исследований по соответствующей теме.\n- **Граница источника:** Вариант 50, задание на НЕ перед заданием 14; вне прежней целевой очереди.\n- **Нормативные основания:** G_NE, LOCAL_PDF; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
