      "sourceMarkdown": "### P12-03 — не смотря\n\nБелецкий с полминуты просидел неподвижно, хмурясь и точно назло (НЕ)СМОТРЯ на меня.\n\n- **Маска:** `(НЕ)СМОТРЯ`; **ответ:** не смотря; **тип:** раздельно.\n- **Грамматика:** Частица не + деепричастие несовершенного вида смотря; на меня — его зависимая группа.\n- **Объяснение:** Белецкий одновременно сидит, хмурится и намеренно не направляет взгляд на рассказчика. Не смотря обозначает отрицаемое добавочное действие того же лица и образует ряд с хмурясь. Наличие на меня не превращает деепричастие в предлог уступки. НЕ пишется раздельно.\n- **Пунктуация и связи:** Обособлен общий ряд деепричастных обстоятельств; перед одиночным и между хмурясь и не смотря запятой нет.\n- **Отличие ситуации:** Намеренное отсутствие зрительного контакта; однородные действия.\n- **Источник:** d50, абзац XML 1177 (от нуля).\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P12.B:** Выбрать слитность по сочетанию на + имя или по наличию запятой. **Стратегия различения:** Найти добавочное зрительное действие того же субъекта и его собственное управление; НЕ с деепричастием отдельно.\n- **Точная исходная строка / транскрипция:** Белецкий с (ПОЛ)МИНУТЫ просидел неподвижно, хмурясь и точно (НА)ЗЛО не смотря на меня.\n- **Реестр:** `research/final_audit/unified_registry.json#/records/36/contexts/0`; `research/final_audit/unified_registry.json#/records/37/contexts/0`. Классификации относятся к прежним целям, а не автоматически к новой.\n- **Граница источника:** Исходное предложение задания 14 из реестра; новая цель раньше была раскрыта.\n- **Нормативные основания:** G_NE, LOCAL_PDF; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
