      "sourceMarkdown": "### P12-04 — не смотря\n\n(НЕ)СМОТРЯ в глаза другу, Валерий пробормотал слова извинения.\n\n- **Маска:** `(НЕ)СМОТРЯ`; **ответ:** не смотря; **тип:** раздельно.\n- **Грамматика:** Частица не + деепричастие несовершенного вида смотря; в глаза другу — зависимая группа.\n- **Объяснение:** Валерий произносит извинение и при этом избегает взгляда в глаза друга. Добавочное зрительное действие соотнесено с подлежащим Валерий; конструкция в глаза зависит от смотря. Это не уступительное обстоятельство, поэтому НЕ с деепричастием раздельно.\n- **Пунктуация и связи:** Начальный деепричастный оборот обособлен; его субъект совпадает с субъектом сказуемого.\n- **Отличие ситуации:** Извинение и взгляд; иное управление без на.\n- **Источник:** Цыбулько, «Отличный результат ЕГЭ 2026»: PDF-страница 187, печатная 192, упражнение 13, пункт 3, второе предложение.\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P12.B:** Выбрать слитность по сочетанию на + имя или по наличию запятой. **Стратегия различения:** Найти добавочное зрительное действие того же субъекта и его собственное управление; НЕ с деепричастием отдельно.\n- **Точная исходная строка / транскрипция:** (Не)смотря в глаза другу, Валерий пробормотал слова извинения.\n- **Нормативные основания:** G_NE, LOCAL_PDF; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
