      "sourceMarkdown": "### P13-01 — невзирая\n\n(НЕ)ВЗИРАЯ на волнение перед важным совещанием, коллеги вели себя сдержанно.\n\n- **Маска:** `(НЕ)ВЗИРАЯ`; **ответ:** невзирая; **тип:** слитно.\n- **Грамматика:** Компонент составного производного уступительного предлога невзирая на; винительный волнение.\n- **Объяснение:** Волнение — обстоятельство, которое могло нарушить сдержанность, но этого не произошло. Зрительного действия взирать здесь нет. Невзирая на выражает уступку; невзирая пишется слитно, на отдельно.\n- **Пунктуация и связи:** Начальный уступительный оборот обособлен.\n- **Отличие ситуации:** Уступка: внутреннее состояние участников.\n- **Источник:** d50, абзац XML 8977 (от нуля).\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P13.A:** Писать не взирая раздельно в значении уступки, особенно в обороте невзирая на лица. **Стратегия различения:** Определить, учитывается ли препятствие/положение лиц: при уступительном отношении это предлог невзирая на.\n- **Точная исходная строка / транскрипция:** (НЕ)ВЗИРАЯ на волнение перед важным совещанием, коллеги вели себя сдержанно.\n- **Граница источника:** Задание на НЕ перед заданием 14; отдельное употребление вне реестра 390 конструкций.\n- **Нормативные основания:** G_NE, G_VZ, G_STYLE; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
