      "sourceMarkdown": "### P15-01 — наподобие\n\nЭпоха реакции, которая наступила в России сразу же после восстания декабристов, породила людей (НА)ПОДОБИЕ Печорина.\n\n- **Маска:** `(НА)ПОДОБИЕ`; **ответ:** наподобие; **тип:** слитно.\n- **Грамматика:** Производный предлог подобия с родительным падежом имени Печорина.\n- **Объяснение:** Предлог наподобие вводит образец, с которым сопоставлены люди определённого типа. Печорина — родительный при предлоге; самостоятельный объект «подобие» не назван. Наподобие пишется слитно с конечным е.\n- **Пунктуация и связи:** Придаточное определительное обособлено с двух сторон; группа наподобие Печорина относится к людей и не обособлена.\n- **Отличие ситуации:** Сравнение социально-литературного типа.\n- **Источник:** Цыбулько, «Отличный результат ЕГЭ 2026»: PDF-страница 338, печатная 343, итоговый контроль, вариант 1, задание 14, пункт 5.\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P15.A:** Разделить наподобие при существительном в родительном. **Стратегия различения:** Предлог вводит образец сравнения; родительный относится к предлогу, самостоятельного объекта подобие нет.\n- **Точная исходная строка / транскрипция:** Эпоха реакции, которая наступила в России СРАЗУ(ЖЕ) после восстания декабристов, породила людей (НА)ПОДОБИЕ Печорина.\n- **Нормативные основания:** N140, G_POD, LOCAL_PDF; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
