      "sourceMarkdown": "### P15-02 — наподобие\n\nНад столом висел светильник (НА)ПОДОБИЕ старинного фонаря.\n\n- **Маска:** `(НА)ПОДОБИЕ`; **ответ:** наподобие; **тип:** слитно.\n- **Грамматика:** Производный предлог с родительным падежом фонаря; отношение подобия.\n- **Объяснение:** Старинный фонарь служит образцом сравнения для светильника. Наподобие связывает предмет и сравнительный образец, управляя родительным фонаря. Это предлог с закреплённым слитным написанием, а не объект наблюдения «подобие».\n- **Пунктуация и связи:** Предложная группа является определением к светильник; обособления не требует.\n- **Отличие ситуации:** Внешняя форма предмета.\n- **Источник:** Авторский; новое предложение для дополнения «Предлоги».\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P15.A:** Разделить наподобие при существительном в родительном. **Стратегия различения:** Предлог вводит образец сравнения; родительный относится к предлогу, самостоятельного объекта подобие нет.\n- **Нормативные основания:** N140, G_POD, LOCAL_PDF; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
