      "sourceMarkdown": "### P16-01 — вроде\n\nСтарый мельник уже давным-давно стал в здешних местах чем-то (В)РОДЕ живой легенды.\n\n- **Маска:** `(В)РОДЕ`; **ответ:** вроде; **тип:** слитно.\n- **Грамматика:** Производный предлог со значением подобия с родительным падежом легенды.\n- **Объяснение:** Вроде живой легенды уточняет, с чем сопоставляется положение мельника. Предлог вводит родительный легенды; он не выражает неуверенность относительно всего сообщения, как частица вроде. Поэтому вроде пишется слитно.\n- **Пунктуация и связи:** Предложное определение при чем-то не обособляется.\n- **Отличие ситуации:** Переносное уподобление человека легенде.\n- **Источник:** d36, абзац XML 3133 (от нуля).\n- **Статус:** готов к согласованию. пригодно к редакторскому согласованию.\n- **Дистрактор P16.A:** Признать вроде частицей или разделить его перед сравнительным образцом. **Стратегия различения:** Распознать предложное управление родительным и связь с определяемым словом; отличить частицу перед целым сообщением.\n- **Точная исходная строка / транскрипция:** Старый мельник уже ДАВНЫМ(ДАВНО) стал в здешних местах ЧЕМ(ТО) вроде живой легенды.\n- **Реестр:** `research/final_audit/unified_registry.json#/records/291/contexts/0`; `research/final_audit/unified_registry.json#/records/292/contexts/0`. Классификации относятся к прежним целям, а не автоматически к новой.\n- **Граница источника:** Исходное предложение задания 14 из реестра; новая цель раньше была раскрыта.\n- **Нормативные основания:** N140, LOCAL_PDF; ссылки в [отчёте](teacher_report.md#нормативные-основания).",
